# ===== COLOR UTILITIES =====

def ansi_color(n: int, bold: bool = False) -> str:
    """Convert color number (0-15) to ANSI escape code."""
    if n < 0:
        n = 39  # default
    if n == 39:
        if bold:
            return '\x1b[39;1m'
        return '\x1b[39m'
    if n < 8:
        code = 30 + n
    else:
        code = 82 + n  # 90 + (n - 8)
    if bold:
        return '\x1b[%d;1m' % code
    return '\x1b[%dm' % code

def ansi_reset() -> str:
    return '\x1b[0m'

def ansi_bg(n: int) -> str:
    """Background color from 0-7."""
    if n == 0:
        return '\x1b[40m'
    return '\x1b[4%dm' % n

def ansi_bg_reset() -> str:
    return '\x1b[49m'

def strip_ansi(s: str) -> str:
    """Remove ANSI escape codes from string."""
    return re.sub(r'\x1b\[[^m]*m', '', s)

def display_width(s: str) -> int:
    """Get display width of string (excluding ANSI codes)."""
    return len(strip_ansi(s))

def color_from_ansi_code(code: int) -> int:
    """Convert ANSI code back to 0-15 color number."""
    if code == 39:
        return 39  # default
    if 30 <= code <= 37:
        return code - 30
    if 90 <= code <= 97:
        return code - 82
    return 39

def apply_ascii_colors(art_lines: List[str], lang_colors: List[int], bold: bool = True) -> List[str]:
    """Apply ascii-colors to art lines by replacing original colors with new ones."""
    if not art_lines:
        return art_lines

    # Find ordered list of unique colors in the art
    original_colors = []
    for line in art_lines:
        for m in re.finditer(r'\x1b\[(\d+);1m', line):
            code = int(m.group(1))
            if code not in original_colors:
                original_colors.append(code)

    # Build replacement mapping
    color_map = {}
    for i, orig_code in enumerate(original_colors):
        if i < len(lang_colors):
            new_color = lang_colors[i]
            if new_color < 8:
                new_code = 30 + new_color
            else:
                new_code = 82 + new_color
            color_map[orig_code] = new_code
        else:
            color_map[orig_code] = orig_code  # Keep original

    result = []
    for line in art_lines:
        new_line = re.sub(
            r'\x1b\[(\d+);1m',
            lambda m: '\x1b[%d;1m' % color_map.get(int(m.group(1)), int(m.group(1))),
            line
        )
        result.append(new_line)

    return result

def get_info_color(ascii_lang_key: Optional[str], ascii_colors: Optional[List[int]], 
                   lang_arts: dict) -> int:
    """Get the primary color code for info text."""
    if ascii_colors and len(ascii_colors) > 0:
        c = ascii_colors[0]
        if c < 8:
            return 30 + c
        return 82 + c

    if ascii_lang_key and ascii_lang_key in lang_arts:
        # Get the primary color from the first color in the art
        art_lines = lang_arts[ascii_lang_key][1]
        for line in art_lines:
            m = re.search(r'\x1b\[(\d+);1m', line)
            if m:
                return int(m.group(1))
        return lang_arts[ascii_lang_key][0]

    return 39  # default

