# ===== TIME FORMATTING =====

def format_time_ago(dt: datetime, iso_time: bool = False) -> str:
    """Format a datetime as 'X time ago' relative to now."""
    if iso_time:
        return dt.strftime('%Y-%m-%dT%H:%M:%SZ')

    now = datetime.now(timezone.utc)
    diff = now - dt
    total_seconds = diff.total_seconds()

    if total_seconds < 60:
        return 'now'

    minutes = total_seconds / 60
    if minutes < 2:
        return 'a minute ago'
    if minutes < 60:
        return '%d minutes ago' % int(minutes)

    hours = minutes / 60
    if hours < 2:
        return 'an hour ago'
    if hours < 24:
        return '%d hours ago' % int(hours)

    days = hours / 24
    if days < 2:
        return 'a day ago'
    if days < 7:
        return '%d days ago' % int(days)

    weeks = days / 7
    if weeks < 2:
        return 'a week ago'
    if weeks < 4:
        return '%d weeks ago' % int(weeks)

    months = days / 30.44
    if months < 2:
        return 'a month ago'
    if months < 12:
        return '%d months ago' % int(months)

    years = days / 365.25
    if years < 2:
        return 'a year ago'
    return '%d years ago' % int(years)

# ===== SIZE FORMATTING =====

def format_size(size_bytes: int) -> str:
    """Format byte size as human-readable string."""
    if size_bytes < 1024:
        return '%d B' % size_bytes
    elif size_bytes < 1024 * 1024:
        kb = size_bytes / 1024.0
        if kb == int(kb):
            return '%.0f KiB' % kb
        else:
            return '%.2f KiB' % kb
    elif size_bytes < 1024 * 1024 * 1024:
        mb = size_bytes / (1024.0 * 1024)
        if mb == int(mb):
            return '%.0f MiB' % mb
        else:
            return '%.2f MiB' % mb
    else:
        gb = size_bytes / (1024.0 * 1024 * 1024)
        if gb == int(gb):
            return '%.0f GiB' % gb
        else:
            return '%.2f GiB' % gb

def format_number(n: int, separator: str = 'plain') -> str:
    """Format number with separator."""
    if separator == 'plain':
        return str(n)
    s = str(n)
    # Insert separator every 3 digits from right
    sep = {'comma': ',', 'space': ' ', 'underscore': '_'}.get(separator, '')
    result = []
    for i, c in enumerate(reversed(s)):
        if i > 0 and i % 3 == 0:
            result.append(sep)
        result.append(c)
    return ''.join(reversed(result))

# ===== GIT OPERATIONS =====

def run_git(args: List[str], cwd: str, check: bool = False) -> Tuple[int, str, str]:
    """Run a git command and return (returncode, stdout, stderr)."""
    try:
        result = subprocess.run(
            ['git'] + args,
            cwd=cwd,
            capture_output=True,
            text=True,
            timeout=30
        )
        return result.returncode, result.stdout, result.stderr
    except subprocess.TimeoutExpired:
        return -1, '', 'timeout'
    except Exception as e:
        return -1, '', str(e)

def get_git_version() -> str:
    """Get git version string."""
    try:
        result = subprocess.run(['git', '--version'], capture_output=True, text=True, timeout=5)
        return result.stdout.strip()
    except:
        return 'git version unknown'

def get_git_username(repo_path: str) -> str:
    """Get git user.name."""
    rc, stdout, _ = run_git(['config', 'user.name'], repo_path)
    if rc == 0:
        return stdout.strip()
    # Try global config
    try:
        result = subprocess.run(['git', 'config', '--global', 'user.name'], 
                               capture_output=True, text=True, timeout=5)
        return result.stdout.strip()
    except:
        return ''

def get_repo_root(path: str) -> Optional[str]:
    """Get the root directory of the git repository."""
    rc, stdout, _ = run_git(['rev-parse', '--show-toplevel'], path)
    if rc == 0:
        return stdout.strip()
    return None

def get_head_info(repo_path: str) -> dict:
    """Get HEAD commit info."""
    # Get short commit hash
    rc, stdout, _ = run_git(['rev-parse', '--short', 'HEAD'], repo_path)
    if rc != 0:
        return {'shortCommitId': '', 'refs': []}

    short_id = stdout.strip()

    # Get branch/tag refs for HEAD
    rc2, stdout2, _ = run_git(['symbolic-ref', '--short', 'HEAD'], repo_path)
    refs = []
    if rc2 == 0:
        refs = [stdout2.strip()]
    else:
        # Detached HEAD - check for tags
        rc3, stdout3, _ = run_git(['describe', '--tags', '--exact-match', 'HEAD'], repo_path)
        if rc3 == 0:
            refs = [stdout3.strip()]

    return {'shortCommitId': short_id, 'refs': refs}

def is_shallow_repo(repo_path: str) -> bool:
