    sep = {'comma': ',', 'space': ' ', 'underscore': '_'}.get(separator, '')
    result = []
    for i, c in enumerate(reversed(s)):
        if i > 0 and i % 3 == 0:
            result.append(sep)
        result.append(c)
    return ''.join(reversed(result))

# ===== GIT OPERATIONS =====

def run_git(args: List[str], cwd: str, check: bool = False) -> Tuple[int, str, str]:
    """Run a git command and return (returncode, stdout, stderr)."""
    try:
        result = subprocess.run(
            ['git'] + args,
            cwd=cwd,
            capture_output=True,
            text=True,
            timeout=30
        )
        return result.returncode, result.stdout, result.stderr
    except subprocess.TimeoutExpired:
        return -1, '', 'timeout'
    except Exception as e:
        return -1, '', str(e)

def get_git_version() -> str:
    """Get git version string."""
    try:
        result = subprocess.run(['git', '--version'], capture_output=True, text=True, timeout=5)
        return result.stdout.strip()
    except:
        return 'git version unknown'

def get_git_username(repo_path: str) -> str:
    """Get git user.name."""
    rc, stdout, _ = run_git(['config', 'user.name'], repo_path)
    if rc == 0:
        return stdout.strip()
    # Try global config
    try:
        result = subprocess.run(['git', 'config', '--global', 'user.name'], 
                               capture_output=True, text=True, timeout=5)
        return result.stdout.strip()
    except:
        return ''

def get_repo_root(path: str) -> Optional[str]:
    """Get the root directory of the git repository."""
    rc, stdout, _ = run_git(['rev-parse', '--show-toplevel'], path)
    if rc == 0:
        return stdout.strip()
    return None

def get_head_info(repo_path: str) -> dict:
    """Get HEAD commit info."""
    # Get short commit hash
    rc, stdout, _ = run_git(['rev-parse', '--short', 'HEAD'], repo_path)
    if rc != 0:
        return {'shortCommitId': '', 'refs': []}

    short_id = stdout.strip()

    # Get branch/tag refs for HEAD
    rc2, stdout2, _ = run_git(['symbolic-ref', '--short', 'HEAD'], repo_path)
    refs = []
    if rc2 == 0:
        refs = [stdout2.strip()]
    else:
        # Detached HEAD - check for tags
        rc3, stdout3, _ = run_git(['describe', '--tags', '--exact-match', 'HEAD'], repo_path)
        if rc3 == 0:
            refs = [stdout3.strip()]

    return {'shortCommitId': short_id, 'refs': refs}

def is_shallow_repo(repo_path: str) -> bool:
    """Check if repo is a shallow clone."""
    shallow_file = os.path.join(repo_path, '.git', 'shallow')
    if not os.path.exists(shallow_file):
        # Check .git is a file (submodule) or directory
        git_dir = os.path.join(repo_path, '.git')
        if os.path.isfile(git_dir):
            return False  # Can't determine for submodules
    return os.path.exists(shallow_file)

def get_pending_changes(repo_path: str) -> dict:
    """Get number of pending (uncommitted) changes."""
    rc, stdout, _ = run_git(['status', '--porcelain'], repo_path)
    if rc != 0:
        return {'added': 0, 'deleted': 0, 'modified': 0}

    added = deleted = modified = 0
    for line in stdout.splitlines():
        if len(line) >= 2:
            xy = line[:2]
            # XY format: X = staged, Y = unstaged
            # We want unstaged changes
            y = xy[1]
            if y == '?':
                added += 1
            elif y == 'D':
                deleted += 1
            elif y == 'M':
                modified += 1
            elif xy == '??':
                pass  # untracked

    # Actually count untracked files and unstaged changes
    added = modified = deleted = 0
    for line in stdout.splitlines():
        if len(line) < 2:
            continue
        x, y = line[0], line[1]
        if x == '?' and y == '?':
            # Untracked file
            added += 1
        elif y == 'M':
            modified += 1
        elif y == 'D':
            deleted += 1
        elif y == 'A':
            added += 1

    return {'added': added, 'deleted': deleted, 'modified': modified}

def get_commits(repo_path: str, no_merges: bool = False, no_bots: Optional[str] = None) -> List[dict]:
    """Get list of commits."""
    args = ['log', '--format=%H|%ae|%an|%ct']
    if no_merges:
        args.append('--no-merges')

    rc, stdout, _ = run_git(args, repo_path)
    if rc != 0:
        return []

    commits = []
    for line in stdout.splitlines():
        if not line:
            continue
        parts = line.split('|', 3)
        if len(parts) >= 4:
            commit_hash, email, name, timestamp = parts
            commits.append({
                'hash': commit_hash,
                'email': email,
                'name': name,
                'timestamp': int(timestamp),
            })

    # Filter bots if requested
    if no_bots is not None:
        if no_bots == '':
            # Default pattern: [bot] in name
            bot_pattern = re.compile(r'\[bot\]', re.IGNORECASE)
        else:
            bot_pattern = re.compile(no_bots, re.IGNORECASE)
        commits = [c for c in commits if not bot_pattern.search(c['name'])]

    return commits

def get_churn(repo_path: str, pool_size: int, no_merges: bool = False) -> Tuple[List[dict], int]:
    """Get file churn data."""
    args = ['log', '--format=%H', '--name-only']
    if no_merges:
        args.append('--no-merges')
    args.extend(['-n', str(pool_size)])

    rc, stdout, _ = run_git(args, repo_path)
    if rc != 0:
        return [], 0

    file_counts = {}
    commit_count = 0
    current_files = []

    for line in stdout.splitlines():
        line = line.strip()
        if not line:
            if current_files:
                commit_count += 1
                for f in current_files:
                    file_counts[f] = file_counts.get(f, 0) + 1
                current_files = []
        elif len(line) == 40 and all(c in '0123456789abcdef' for c in line):
            if current_files:
                commit_count += 1
                for f in current_files:
                    file_counts[f] = file_counts.get(f, 0) + 1
                current_files = []
        else:
            current_files.append(line)

    if current_files:
        commit_count += 1
        for f in current_files:
            file_counts[f] = file_counts.get(f, 0) + 1

    # Sort by count descending, then by file path
    churns = sorted(file_counts.items(), key=lambda x: (-x[1], x[0]))
    return [{'filePath': f, 'nbrOfCommits': c} for f, c in churns], commit_count

def get_remote_url(repo_path: str) -> str:
    """Get remote origin URL."""
    rc, stdout, _ = run_git(['remote', 'get-url', 'origin'], repo_path)
    if rc == 0:
        return stdout.strip()
    rc2, stdout2, _ = run_git(['config', '--get', 'remote.origin.url'], repo_path)
    if rc2 == 0:
        return stdout2.strip()
    return ''

def process_url(url: str, http_url: bool = False, hide_token: bool = False) -> str:
    """Process repository URL."""
    if not url:
        return url

    # Convert SSH to HTTPS if requested
    if http_url:
        # git@github.com:user/repo.git -> https://github.com/user/repo.git
        ssh_match = re.match(r'^git@([^:]+):(.+)$', url)
        if ssh_match:
            host = ssh_match.group(1)
            path = ssh_match.group(2)
            url = 'https://%s/%s' % (host, path)

    # Handle credentials in URL
    cred_match = re.match(r'^(https?://)([^:@]+):([^@]+)@(.+)$', url)
    if cred_match:
        scheme = cred_match.group(1)
        user = cred_match.group(2)
        password = cred_match.group(3)
        rest = cred_match.group(4)

        if hide_token:
            # Remove credentials entirely
            url = scheme + rest
        else:
            # Replace password with "redacted"
            url = '%s%s:redacted@%s' % (scheme, user, rest)

    return url

def get_tags_count(repo_path: str) -> int:
    """Get number of tags."""
    rc, stdout, _ = run_git(['tag'], repo_path)
    if rc != 0:
        return 0
    return len([t for t in stdout.splitlines() if t.strip()])

def get_branches_count(repo_path: str) -> int:
    """Get number of remote branches."""
    rc, stdout, _ = run_git(['branch', '-r'], repo_path)
    if rc != 0:
        return 0
    return len([b for b in stdout.splitlines() if b.strip()])

def get_repo_name(remote_url: str) -> str:
    """Extract repo name from remote URL."""
    if not remote_url:
        return ''
    # Remove .git suffix
    url = re.sub(r'\.git$', '', remote_url)
    # Extract last path component
    parts = re.split(r'[/:]', url)
    if parts:
        return parts[-1]
    return ''

def get_version_and_description(repo_path: str) -> Tuple[str, Optional[str]]:
    """Get version and description from package files."""
    # Check package.json
    pkg_json = os.path.join(repo_path, 'package.json')
    if os.path.exists(pkg_json):
        try:
            with open(pkg_json, 'r', encoding='utf-8', errors='ignore') as f:
                pkg = json.load(f)
            version = pkg.get('version', '') or ''
            description = pkg.get('description') or None
            return str(version), description
        except:
            pass

    # Check Cargo.toml
    cargo = os.path.join(repo_path, 'Cargo.toml')
    if os.path.exists(cargo):
        try:
            with open(cargo, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
            # Parse [package] section
            in_package = False
            version = ''
            for line in content.splitlines():
                if re.match(r'^\[package\]', line):
                    in_package = True
                elif re.match(r'^\[', line) and in_package:
                    break
                elif in_package:
                    m = re.match(r'^version\s*=\s*"([^"]+)"', line)
                    if m:
                        version = m.group(1)
            return version, None
        except:
            pass

    # Check pyproject.toml
    pyproject = os.path.join(repo_path, 'pyproject.toml')
    if os.path.exists(pyproject):
        try:
            with open(pyproject, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
            in_project = False
            version = ''
            description = None
            for line in content.splitlines():
                if re.match(r'^\[project\]', line):
                    in_project = True
                elif re.match(r'^\[', line) and in_project:
                    break
                elif in_project:
                    m = re.match(r'^version\s*=\s*"([^"]+)"', line)
                    if m:
                        version = m.group(1)
                    m = re.match(r'^description\s*=\s*"([^"]+)"', line)
                    if m:
                        description = m.group(1)
            if version or description:
                return version, description
        except:
            pass

    # Check setup.py (simple version)
    setup_py = os.path.join(repo_path, 'setup.py')
    if os.path.exists(setup_py):
        try:
            with open(setup_py, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
            m = re.search(r'version\s*=\s*["\']([^"\']+)["\']', content)
            version = m.group(1) if m else ''
            m2 = re.search(r'description\s*=\s*["\']([^"\']+)["\']', content)
            description = m2.group(1) if m2 else None
            if version or description:
                return version, description
        except:
            pass

    return '', None

def get_license(repo_path: str) -> str:
    """Detect license type from license file."""
    license_files = ['LICENSE', 'LICENSE.md', 'LICENSE.txt', 'LICENCE', 'LICENCE.md',
                     'license', 'license.md', 'license.txt', 'COPYING', 'COPYING.md']

    for lf in license_files:
        path = os.path.join(repo_path, lf)
        if os.path.exists(path):
            try:
                with open(path, 'r', encoding='utf-8', errors='ignore') as f:
                    content = f.read(4096)

                content_lower = content.lower()

                if 'mit license' in content_lower or content.startswith('MIT License'):
                    return 'MIT'
                elif 'apache license' in content_lower and 'version 2' in content_lower:
                    return 'Apache-2.0'
                elif 'gnu general public license' in content_lower:
                    if 'version 3' in content_lower:
                        return 'GPL-3.0'
                    elif 'version 2' in content_lower:
                        return 'GPL-2.0'
                    return 'GPL'
                elif 'gnu lesser general public license' in content_lower:
                    if 'version 3' in content_lower:
                        return 'LGPL-3.0'
                    return 'LGPL'
                elif 'bsd 2-clause' in content_lower or 'simplified bsd' in content_lower:
                    return 'BSD-2-Clause'
                elif 'bsd 3-clause' in content_lower or 'new bsd license' in content_lower or 'revised bsd' in content_lower:
                    return 'BSD-3-Clause'
                elif 'mozilla public license' in content_lower:
                    return 'MPL-2.0'
                elif 'isc license' in content_lower or content.startswith('ISC License'):
                    return 'ISC'
                elif 'creative commons' in content_lower:
                    if 'cc0' in content_lower or 'public domain' in content_lower:
                        return 'CC0-1.0'
                    return 'CC'
                elif 'unlicense' in content_lower:
                    return 'Unlicense'
                elif 'boost software license' in content_lower:
                    return 'BSL-1.0'
                elif 'the mit license' in content_lower:
                    return 'MIT'
            except:
                pass

    return ''

def get_dependencies(repo_path: str) -> str:
    """Get dependency count from package managers."""
    # Check Cargo.toml
    cargo = os.path.join(repo_path, 'Cargo.toml')
    if os.path.exists(cargo):
        try:
            with open(cargo, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
            # Find [dependencies] section
            in_deps = False
            count = 0
            for line in content.splitlines():
                if re.match(r'^\[dependencies\]', line):
                    in_deps = True
                elif re.match(r'^\[', line) and in_deps:
                    break
                elif in_deps and line.strip() and not line.strip().startswith('#'):
                    if '=' in line:
                        count += 1
            if count > 0:
                return '%d (Cargo)' % count
        except:
            pass

    # Check package.json
    pkg_json = os.path.join(repo_path, 'package.json')
    if os.path.exists(pkg_json):
        try:
            with open(pkg_json, 'r', encoding='utf-8', errors='ignore') as f:
                pkg = json.load(f)
            count = len(pkg.get('dependencies', {}))
            if count > 0:
                return '%d (Npm)' % count
        except:
            pass

    return ''

