# ===== LANGUAGE DETECTION & CODE COUNTING =====

def get_file_language(filepath: str) -> Optional[Tuple[str, str]]:
    """Get language name and type for a file. Returns (lang_name, lang_type) or None."""
    filename = os.path.basename(filepath)

    # Check exact filename matches first
    exact_matches = {
        'CMakeLists.txt': ('CMake', 'programming'),
        'Makefile': ('Makefile', 'programming'),
        'makefile': ('Makefile', 'programming'),
        'GNUmakefile': ('Makefile', 'programming'),
        'Dockerfile': ('Dockerfile', 'programming'),
        'dockerfile': ('Dockerfile', 'programming'),
    }
    if filename in exact_matches:
        return exact_matches[filename]

    # Check extension
    _, ext = os.path.splitext(filename)
    if ext in LANGUAGE_MAP:
        return LANGUAGE_MAP[ext]

    # Check uppercase extension
    if ext.lower() in LANGUAGE_MAP:
        return LANGUAGE_MAP[ext.lower()]

    return None

def count_code_lines(filepath: str, lang_name: str) -> int:
    """Count code lines (non-blank, non-comment) in a file."""
    try:
        with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
            lines = f.readlines()
    except:
        return 0

    if not lines:
        return 0

    # Get comment syntax for this language
    syntax = COMMENT_SYNTAX.get(lang_name, ([], None, None))
    if syntax is None:
        syntax = ([], None, None)
    single_prefixes, block_start, block_end = syntax

    code_count = 0
    in_block_comment = False

    for line in lines:
        stripped = line.strip()

        if not stripped:
            continue  # blank line

        if in_block_comment:
            if block_end and block_end in stripped:
                # Check if there's code after the block end
                idx = stripped.find(block_end)
                remaining = stripped[idx + len(block_end):].strip()
                if remaining and not remaining.startswith(tuple(single_prefixes) if single_prefixes else ('',)):
                    code_count += 1
                in_block_comment = False
            # Still in block comment
            continue

        # Check for block comment start
        if block_start and stripped.startswith(block_start):
            if block_end and block_end != block_start and block_end in stripped[len(block_start):]:
                # Single-line block comment
                remaining = stripped[stripped.find(block_end, len(block_start)) + len(block_end):].strip()
                if remaining:
                    code_count += 1
            elif block_end == block_start:
                # Triple-quote style (Python docstrings, CoffeeScript)
                # Count remaining quote occurrences
                rest = stripped[len(block_start):]
                if block_end in rest:
                    # Single-line block comment/string
                    code_count += 1  # Lines with triple-quotes count
                else:
                    in_block_comment = True
                    code_count += 1  # The opening line counts? No...
                    # Actually, for Python, triple-quoted strings are code
            else:
                in_block_comment = True
            continue

        # Check for inline block comment start
        if block_start and block_start in stripped:
            # Block comment starts in the middle of a line
            # This line has code before the comment
            code_before = stripped[:stripped.find(block_start)].strip()
            if code_before:
                code_count += 1
                if block_end and block_end in stripped[stripped.find(block_start) + len(block_start):]:
                    pass  # Block comment ends on same line
                else:
                    in_block_comment = True
            else:
                # Block comment is at start
                if block_end and block_end in stripped[len(block_start):]:
                    pass  # Single line block comment
                else:
                    in_block_comment = True
            continue

        # Check for single-line comments
        is_comment = False
        for prefix in single_prefixes:
            if stripped.startswith(prefix):
                is_comment = True
                break

        if is_comment:
            continue

        code_count += 1

    return code_count

def get_gitignore_patterns(repo_path: str) -> List[str]:
    """Read .gitignore patterns."""
    patterns = []
    gitignore = os.path.join(repo_path, '.gitignore')
    if os.path.exists(gitignore):
        try:
            with open(gitignore, 'r', encoding='utf-8', errors='ignore') as f:
                for line in f:
                    line = line.rstrip('\n')
                    if line and not line.startswith('#'):
                        patterns.append(line)
        except:
            pass
    return patterns

def is_ignored(path: str, repo_path: str, patterns: List[str]) -> bool:
    """Check if a path is ignored by gitignore patterns."""
    rel_path = os.path.relpath(path, repo_path)

    # Always ignore .git directory
    parts = rel_path.split(os.sep)
    if '.git' in parts:
        return True

    for pattern in patterns:
        # Convert gitignore pattern to simple match
        if pattern.endswith('/'):
            # Directory pattern
            dir_pattern = pattern.rstrip('/')
            if parts[0] == dir_pattern:
                return True
            for part in parts[:-1]:
                if part == dir_pattern:
                    return True
        elif '*' in pattern or '?' in pattern:
            # Glob pattern
            import fnmatch
            basename = os.path.basename(rel_path)
            if fnmatch.fnmatch(basename, pattern):
                return True
            if fnmatch.fnmatch(rel_path, pattern):
                return True
        else:
            # Exact match or prefix
            if rel_path == pattern or rel_path.startswith(pattern + '/'):
                return True
            basename = os.path.basename(rel_path)
            if basename == pattern:
                return True

    return False

def count_languages(repo_path: str, exclude_patterns: List[str] = None,
                    include_hidden: bool = False,
                    type_filter: List[str] = None) -> Dict[str, int]:
    """Count code lines per language in the repository."""
    if type_filter is None:
        type_filter = ['programming', 'markup']

    if exclude_patterns is None:
        exclude_patterns = []

    gitignore_patterns = get_gitignore_patterns(repo_path)
    all_ignore_patterns = gitignore_patterns + exclude_patterns

    lang_counts = {}

    for root, dirs, files in os.walk(repo_path):
        # Filter hidden directories unless --include-hidden
        if not include_hidden:
            dirs[:] = [d for d in dirs if not d.startswith('.')]
        else:
            dirs[:] = [d for d in dirs if d != '.git']

        # Check if this directory is ignored
        if is_ignored(root, repo_path, all_ignore_patterns) and root != repo_path:
            dirs[:] = []
            continue

        for filename in files:
            # Skip hidden files unless --include-hidden
            if not include_hidden and filename.startswith('.'):
                continue

            filepath = os.path.join(root, filename)

            # Check if file is ignored
            if is_ignored(filepath, repo_path, all_ignore_patterns):
                continue

            # Check for exclude patterns  
            rel_path = os.path.relpath(filepath, repo_path)
            excluded = False
            for pat in exclude_patterns:
                import fnmatch
                if fnmatch.fnmatch(rel_path, pat) or fnmatch.fnmatch(filename, pat):
                    excluded = True
                    break
            if excluded:
                continue

            lang_info = get_file_language(filepath)
            if lang_info is None:
                continue

            lang_name, lang_type = lang_info

            if lang_type not in type_filter:
                continue

            code_lines = count_code_lines(filepath, lang_name)
            if code_lines > 0:
                lang_counts[lang_name] = lang_counts.get(lang_name, 0) + code_lines

    return lang_counts

def get_tracked_files(repo_path: str) -> List[str]:
    """Get list of all git-tracked files."""
    rc, stdout, _ = run_git(['ls-files'], repo_path)
    if rc != 0:
        return []
    return [f for f in stdout.splitlines() if f]

def get_repo_size_and_count(repo_path: str) -> Tuple[int, int]:
    """Get total size of tracked files and file count."""
    tracked_files = get_tracked_files(repo_path)
    total_size = 0
    file_count = 0

    for rel_path in tracked_files:
        filepath = os.path.join(repo_path, rel_path)
        if os.path.isfile(filepath):
            try:
                total_size += os.path.getsize(filepath)
                file_count += 1
            except:
                pass

    return total_size, file_count

