# ===== DISPLAY RENDERING =====

def render_language_bar(languages: List[Tuple[str, float]], max_langs: int) -> Tuple[str, str]:
    """Render the language percentage bar and legend.
    Returns (bar_line, legend_text) where legend_text may contain newlines.
    """
    if not languages:
        return '', ''

    total_width = 26  # base width

    # Prepare display languages (top N + Other if needed)
    if len(languages) > max_langs:
        shown = languages[:max_langs]
        other_pct = sum(p for _, p in languages[max_langs:])
        shown_with_other = shown + [('Other', other_pct)]
    else:
        shown_with_other = list(languages)

    # Calculate bar widths using round-half-up
    bar_widths = []
    for _, pct in shown_with_other:
        width = math.floor(pct / 100.0 * total_width + 0.5)
        bar_widths.append(max(1, width))

    # Build bar line
    bar_parts = []
    for i, (lang, pct) in enumerate(shown_with_other):
        color_idx = min(i + 1, 7)  # colors 1-7
        width = bar_widths[i]
        if width > 0:
            bar_parts.append(ansi_bg(color_idx) + ' ' * width + ansi_bg_reset())

    bar_line = ''.join(bar_parts) + ansi_reset()

    # Build legend lines (2 langs per line)
    legend_lines = []
    for i, (lang, pct) in enumerate(shown_with_other):
        color_idx = min(i + 1, 7)
        # Format percentage
        if pct == int(pct):
            pct_str = '%.1f %%' % pct
        else:
            # Show 1 decimal place
            pct_str = '%.1f %%' % pct

        # Get display name
        display_name = LANGUAGE_DISPLAY_NAMES.get(lang, lang)

        # Color for bullet
        if color_idx < 8:
            bullet_code = 30 + color_idx
        else:
            bullet_code = 82 + color_idx

        entry = '\x1b[%dm\u25cf\x1b[39m \x1b[39m%s (%s)\x1b[39m' % (
            bullet_code, display_name, pct_str
        )

        if i % 2 == 0:
            legend_lines.append(entry)
        else:
            legend_lines[-1] = legend_lines[-1] + ' ' + entry

    return bar_line, '\n'.join('           ' + l for l in legend_lines)


