def render_with_art(title: str, separator: str, fields: List[Tuple[str, str]],
                    art_lines: List[str], info_color: int, config: dict) -> str:
    """Render output with ASCII art on left side."""
    no_bold = config.get('no_bold', False)
    no_color_palette = config.get('no_color_palette', False)
    no_title = config.get('no_title', False)

    bold_info = '' if no_bold else ';1'

    # Expand multi-line fields into individual lines with continuation indent
    info_lines = []

    if not no_title:
        title_line = '%s%s\x1b[0m \x1b[39%sm~\x1b[0m %s%s\x1b[0m' % (
            '\x1b[%d%sm' % (info_color, bold_info),
            title,
            bold_info,
            '\x1b[%d%sm' % (info_color, bold_info),
            'git %s' % config.get('git_version', 'version unknown')
        )
        info_lines.append(title_line)
        info_lines.append('\x1b[39m%s\x1b[39m' % separator)

    for label, value in fields:
        label_color = '\x1b[%d%sm' % (info_color if info_color != 39 else 39, bold_info)
        colon_color = '\x1b[39%sm' % bold_info
        value_color = '\x1b[39m'

        value_parts = value.split('\n')
        first_line = '%s%s\x1b[0m%s:\x1b[0m %s%s\x1b[0m' % (
            label_color, label, colon_color, value_color, value_parts[0]
        )
        info_lines.append(first_line)
        for extra in value_parts[1:]:
            info_lines.append(value_color + extra + '\x1b[0m')

    if not no_color_palette:
        info_lines.append('')
        palette = ''.join('\x1b[4%dm   \x1b[49m' % i for i in range(8))
        info_lines.append(palette)

    # Combine art lines with info lines
    # Art column is 40 chars wide, 2 space gap, then info
    max_lines = max(len(art_lines), len(info_lines))

    # Pad art and info arrays
    padded_art = art_lines + [''] * max(0, max_lines - len(art_lines))
    padded_info = info_lines + [''] * max(0, max_lines - len(info_lines))

    output_lines = ['\x1b[?7l']

    for i in range(max_lines):
        art = padded_art[i] if i < len(padded_art) else ''
        info = padded_info[i] if i < len(padded_info) else ''

        # Calculate display width of art part
        art_display_width = display_width(art)

        # Pad art to 40 chars
        padding_needed = max(0, 40 - art_display_width)

        # Build the line
        line_parts = ['\x1b[39;1m\x1b[0m']  # standard prefix
        if art:
            line_parts.append(art + '\x1b[0m')
        line_parts.append(' ' * padding_needed)

        if info:
            line_parts.append('   ' + info)  # 3-space gap

        output_lines.append(''.join(line_parts))

    output_lines.append('\x1b[?7h')
    return '\n'.join(output_lines)


def render_ascii_art(art_data: Tuple[int, List[str]], ascii_colors: Optional[List[int]], 
                     lang_arts: dict, ascii_lang_key: Optional[str]) -> Tuple[List[str], int]:
    """Render ASCII art with applied colors. Returns (art_lines, info_color)."""
    primary, art_lines = art_data

    if not art_lines:
        return [], 39

    # Find ordered colors in the art
    original_colors = []
    for line in art_lines:
        for m in re.finditer(r'\x1b\[(\d+);1m', line):
            code = int(m.group(1))
            if code not in original_colors:
                original_colors.append(code)

    # Determine info color
    if ascii_colors and len(ascii_colors) > 0:
        c = ascii_colors[0]
        if c < 8:
            info_code = 30 + c
        else:
            info_code = 82 + c
    else:
        # Use primary color from art
        info_code = original_colors[0] if original_colors else primary

    # Apply color substitution
    if ascii_colors:
        # Build color replacement map
        color_map = {}
        for i, orig_code in enumerate(original_colors):
            if i < len(ascii_colors):
                new_color = ascii_colors[i]
                if new_color < 8:
                    color_map[orig_code] = 30 + new_color
                else:
                    color_map[orig_code] = 82 + new_color
            else:
                color_map[orig_code] = orig_code

        new_art = []
        for line in art_lines:
            new_line = re.sub(
                r'\x1b\[(\d+);1m',
                lambda m: '\x1b[%d;1m' % color_map.get(int(m.group(1)), int(m.group(1))),
                line
            )
            new_art.append(new_line)
        art_lines = new_art

    return art_lines, info_code


