# Now fix the YAML quoting issue
# Original: "name: github-actions[bot]" (unquoted)
# Mine: "name: 'github-actions[bot]'" (quoted because of [ ])
# The original serde_yaml seems to handle "[" and "]" differently

# Actually, YAML spec says a string starting with '[' is an indicator (flow sequence)
# But "github-actions[bot]" doesn't start with '[', so it shouldn't need quoting
# But my yaml_scalar function quotes strings containing '[' or ']'

python3 << 'FIX_YAML_QUOTING'
with open('/workspace/onefetch-impl/src/onefetch.py', 'r') as f:
    content = f.read()

# Fix yaml_scalar to match serde_yaml's quoting behavior
old_yaml_scalar = '''def yaml_scalar(v):
    """Convert a scalar value to YAML format."""
    if v is None:
        return 'null'
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        if v == int(v):
            return '%.1f' % v
        return repr(v)
    if isinstance(v, str):
        # Check if string needs quoting
        if not v or v.lower() in ('null', 'true', 'false') or v[0] in ('-', '[', '{', "\'", '"', '|', '>'):
            return "'" + v.replace("'", "''") + "'"
        # Check for special chars
        if any(c in v for c in [':', '#', ',', '[', ']', '{', '}', '&', '*', '!', '|', '>', "\'", '"', '%', '@', '`']):
            if "'" not in v:
                return "'" + v + "'"
            return '"' + v.replace('"', '\\\\"') + '"'
        return v
    return str(v)'''

new_yaml_scalar = '''def yaml_scalar(v):
    """Convert a scalar value to YAML format matching serde_yaml output."""
    if v is None:
        return 'null'
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        if v == int(v):
            return '%.1f' % v
        return repr(v)
    if isinstance(v, str):
        if not v:
            return "''"
        # Check if string needs quoting (following serde_yaml rules)
        # Must quote if: starts with special char, is a YAML keyword, or contains certain chars
        needs_quote = False

        # YAML special starting chars
        if v[0] in ('-', '?', ':', ',', '[', ']', '{', '}', '#', '&', '*', '!', '|', '>', "'", '"', '%', '@', '`'):
            needs_quote = True
        # YAML keywords
        elif v.lower() in ('null', 'true', 'false', 'yes', 'no', 'on', 'off', '~'):
            needs_quote = True
        # Contains colon followed by space (YAML key indicator)
        elif ': ' in v or v.endswith(':'):
            needs_quote = True
        # Contains #  (comment indicator)
        elif ' #' in v:
            needs_quote = True

        if needs_quote:
            # Use single quotes, escape internal single quotes
            return "'" + v.replace("'", "''") + "'"
        return v
    return str(v)'''

content = content.replace(old_yaml_scalar, new_yaml_scalar)

with open('/workspace/onefetch-impl/src/onefetch.py', 'w') as f:
    f.write(content)

print("Fixed YAML quoting")
FIX_YAML_QUOTING
