# Python's %.2f uses banker's rounding (rounds 0.5 to even)
# Original Rust uses standard rounding (rounds 0.5 up)
# Need to use round-half-up for size display

python3 << 'FIX_SIZE'
with open('/workspace/onefetch-impl/src/onefetch.py', 'r') as f:
    content = f.read()

old_size = '''def format_size(size_bytes: int) -> str:
    """Format byte size as human-readable string."""
    if size_bytes < 1024:
        return '%d B' % size_bytes
    elif size_bytes < 1024 * 1024:
        kb = size_bytes / 1024.0
        if kb == int(kb):
            return '%.0f KiB' % kb
        else:
            return '%.2f KiB' % kb
    elif size_bytes < 1024 * 1024 * 1024:
        mb = size_bytes / (1024.0 * 1024)
        if mb == int(mb):
            return '%.0f MiB' % mb
        else:
            return '%.2f MiB' % mb
    else:
        gb = size_bytes / (1024.0 * 1024 * 1024)
        if gb == int(gb):
            return '%.0f GiB' % gb
        else:
            return '%.2f GiB' % gb'''

new_size = '''def format_size(size_bytes: int) -> str:
    """Format byte size as human-readable string (using round-half-up for 2dp)."""
    def round_half_up_2dp(x):
        """Round to 2 decimal places using round-half-up."""
        return math.floor(x * 100 + 0.5) / 100

    if size_bytes < 1024:
        return '%d B' % size_bytes
    elif size_bytes < 1024 * 1024:
        kb = round_half_up_2dp(size_bytes / 1024.0)
        if kb == int(kb):
            return '%.0f KiB' % kb
        else:
            return '%.2f KiB' % kb
    elif size_bytes < 1024 * 1024 * 1024:
        mb = round_half_up_2dp(size_bytes / (1024.0 * 1024))
        if mb == int(mb):
            return '%.0f MiB' % mb
        else:
            return '%.2f MiB' % mb
    else:
        gb = round_half_up_2dp(size_bytes / (1024.0 * 1024 * 1024))
        if gb == int(gb):
            return '%.0f GiB' % gb
        else:
            return '%.2f GiB' % gb'''

content = content.replace(old_size, new_size)

with open('/workspace/onefetch-impl/src/onefetch.py', 'w') as f:
    f.write(content)

print("Fixed size rounding")
